import {
  type ReactNode,
  type KeyboardEvent,
  useState,
  useRef,
  useEffect,
  useCallback,
  createContext,
  useContext,
} from 'react';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

const ChevronDown = () => (
  <svg width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M6 9l6 6 6-6" />
  </svg>
);

/* ---- Context ---- */

type SelectContextValue = {
  open: boolean;
  setOpen: (v: boolean) => void;
  value: string;
  onSelect: (value: string, label: string) => void;
  highlightedIndex: number;
  setHighlightedIndex: (i: number) => void;
  items: string[];
  registerItem: (value: string) => void;
  unregisterItem: (value: string) => void;
  selectedLabel: string;
};

const SelectContext = createContext<SelectContextValue | null>(null);

function useSelect() {
  const ctx = useContext(SelectContext);
  if (!ctx) throw new Error('Select components must be used within <Select>');
  return ctx;
}

/* ---- Root ---- */

export type SelectProps = {
  value?: string;
  onValueChange?: (value: string) => void;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: ReactNode;
  className?: string;
};

export function Select({
  value: controlledValue,
  onValueChange,
  open: controlledOpen,
  onOpenChange,
  children,
  className,
}: SelectProps) {
  const [internalValue, setInternalValue] = useState('');
  const [internalOpen, setInternalOpen] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const [items, setItems] = useState<string[]>([]);
  const [selectedLabel, setSelectedLabel] = useState('');
  const rootRef = useRef<HTMLDivElement>(null);

  const value = controlledValue ?? internalValue;
  const open = controlledOpen ?? internalOpen;

  const setOpen = useCallback(
    (v: boolean) => {
      onOpenChange ? onOpenChange(v) : setInternalOpen(v);
      if (!v) setHighlightedIndex(-1);
    },
    [onOpenChange],
  );

  const onSelect = useCallback(
    (v: string, label: string) => {
      onValueChange ? onValueChange(v) : setInternalValue(v);
      setSelectedLabel(label);
      setOpen(false);
    },
    [onValueChange, setOpen],
  );

  const registerItem = useCallback((v: string) => {
    setItems((prev) => (prev.includes(v) ? prev : [...prev, v]));
  }, []);

  const unregisterItem = useCallback((v: string) => {
    setItems((prev) => prev.filter((item) => item !== v));
  }, []);

  useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open, setOpen]);

  useEffect(() => {
    if (!open) return;
    const handler = (e: globalThis.KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [open, setOpen]);

  return (
    <SelectContext.Provider
      value={{ open, setOpen, value, onSelect, highlightedIndex, setHighlightedIndex, items, registerItem, unregisterItem, selectedLabel }}
    >
      <div ref={rootRef} className={cn('select', className)}>
        {children}
      </div>
    </SelectContext.Provider>
  );
}

/* ---- Trigger ---- */

export type SelectTriggerProps = {
  placeholder?: string;
  disabled?: boolean;
  invalid?: boolean;
  children?: ReactNode;
  className?: string;
};

export function SelectTrigger({
  placeholder = 'Select...',
  disabled = false,
  invalid = false,
  children,
  className,
}: SelectTriggerProps) {
  const { open, setOpen, value, selectedLabel, highlightedIndex, setHighlightedIndex, items, onSelect } = useSelect();

  const handleKeyDown = (e: KeyboardEvent<HTMLButtonElement>) => {
    if (e.key === 'ArrowDown' || e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (!open) {
        setOpen(true);
      } else if (e.key === 'ArrowDown') {
        setHighlightedIndex(highlightedIndex < items.length - 1 ? highlightedIndex + 1 : 0);
      } else if (e.key === 'Enter' && highlightedIndex >= 0) {
        const item = items[highlightedIndex];
        if (item) onSelect(item, item);
      }
    } else if (e.key === 'ArrowUp' && open) {
      e.preventDefault();
      setHighlightedIndex(highlightedIndex > 0 ? highlightedIndex - 1 : items.length - 1);
    }
  };

  const displayValue = children || (value ? selectedLabel || value : null);

  return (
    <button
      type="button"
      role="listbox"
      aria-expanded={open}
      aria-haspopup="listbox"
      aria-invalid={invalid || undefined}
      disabled={disabled}
      className={cn(
        'select__trigger',
        open && 'select__trigger--open',
        disabled && 'select__trigger--disabled',
        className,
      )}
      onClick={() => setOpen(!open)}
      onKeyDown={handleKeyDown}
    >
      <span className={cn('select__value', !displayValue && 'select__value--placeholder')}>
        {displayValue || placeholder}
      </span>
      <span className="select__icon">
        <ChevronDown />
      </span>
    </button>
  );
}

/* ---- Content ---- */

export function SelectContent({ children, className }: { children: ReactNode; className?: string }) {
  const { open } = useSelect();
  if (!open) return null;
  return <div className={cn('select__content', className)}>{children}</div>;
}

/* ---- Group ---- */

export function SelectGroup({
  label,
  children,
  className,
}: {
  label?: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    <div role="group" aria-label={label} className={className}>
      {label && <div className="select__label">{label}</div>}
      <ul className="select__group-list">{children}</ul>
    </div>
  );
}

/* ---- Item ---- */

export type SelectItemProps = {
  value: string;
  disabled?: boolean;
  children?: ReactNode;
  className?: string;
};

export function SelectItem({ value: itemValue, disabled = false, children, className }: SelectItemProps) {
  const { value, onSelect, highlightedIndex, items, registerItem, unregisterItem } = useSelect();

  const isSelected = value === itemValue;
  const index = items.indexOf(itemValue);
  const isHighlighted = index === highlightedIndex;
  const label = typeof children === 'string' ? children : itemValue;

  useEffect(() => {
    registerItem(itemValue);
    return () => unregisterItem(itemValue);
  }, [itemValue, registerItem, unregisterItem]);

  return (
    <li
      role="option"
      aria-selected={isSelected}
      aria-disabled={disabled || undefined}
      className={cn(
        'select__item',
        isSelected && 'select__item--selected',
        isHighlighted && 'select__item--highlighted',
        disabled && 'select__item--disabled',
        className,
      )}
      onClick={() => {
        if (!disabled) onSelect(itemValue, label);
      }}
    >
      {children || itemValue}
    </li>
  );
}

/* ---- Separator ---- */

export function SelectSeparator({ className }: { className?: string }) {
  return <div role="separator" className={cn('select__separator', className)} />;
}

/* -------------------------------------------------------------------------
   Select

   Dropdown picker. Trigger + floating list, no search.
   Composable: Select > Trigger + Content > Group + Label + Item

   Parts: .select, .select__trigger, .select__value, .select__content,
          .select__item, .select__label, .select__separator
   ------------------------------------------------------------------------- */

/* ---- Root ---- */

.select {
  position: relative;
  display: flex;
  width: 100%;
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
}

/* ---- Trigger ---- */

.select__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-2, 8px);
  width: 100%;
  height: var(--spacing-10, 40px);
  padding: 0 var(--spacing-3, 12px);
  border: var(--stroke-hairline) solid var(--border-input);
  border-radius: var(--radius-md);
  background-color: var(--background);
  color: var(--foreground);
  font-family: inherit;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-regular);
  line-height: 1;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    border-color var(--duration-150) var(--easing-in-out),
    box-shadow var(--duration-150) var(--easing-in-out);
}

.select__trigger:hover {
  border-color: var(--border-focus);
}

.select__trigger:focus-visible {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 var(--focus-ring-width, 2px) var(--focus-ring-color);
  outline: none;
}

.select__trigger--open {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 var(--focus-ring-width, 2px) var(--focus-ring-color);
}

.select__trigger--disabled {
  background-color: var(--muted);
  border-color: var(--muted);
  color: var(--muted-foreground);
  cursor: not-allowed;
  pointer-events: none;
}

.select__trigger[aria-invalid="true"] {
  border-color: var(--destructive);
  box-shadow: 0 0 var(--focus-ring-width, 2px) 0 var(--focus-ring-error-color);
}

.select__trigger[aria-invalid="true"]:focus-visible,
.select__trigger[aria-invalid="true"].select__trigger--open {
  border-color: var(--destructive);
  box-shadow: 0 0 0 var(--focus-ring-width, 2px) var(--focus-ring-error-color);
}

/* ---- Value ---- */

.select__value {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.select__value--placeholder {
  color: var(--placeholder);
}

/* ---- Chevron ---- */

.select__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
  color: var(--muted-foreground);
  transition: transform var(--duration-200) var(--easing-in-out);
}

.select__trigger--open .select__icon {
  transform: rotate(180deg);
}

/* ---- Content ---- */

.select__content {
  position: absolute;
  top: calc(100% + var(--spacing-1, 4px));
  left: 0;
  z-index: var(--z-index-20);
  width: 100%;
  min-width: 160px;
  max-height: 256px;
  overflow-y: auto;
  border: var(--stroke-hairline) solid var(--border);
  border-radius: var(--radius-lg);
  background-color: var(--popover);
  color: var(--popover-foreground);
  box-shadow: var(--shadow-md);
  padding: var(--spacing-1, 4px);
  transform-origin: top;
  animation: select-in var(--duration-200) var(--easing-out);
}

@keyframes select-in {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(-4px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

/* ---- Label ---- */

.select__label {
  padding: var(--spacing-2, 8px) var(--spacing-2, 8px) var(--spacing-1, 4px);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-medium);
  color: var(--muted-foreground);
  letter-spacing: var(--letter-spacing-wide);
  text-transform: uppercase;
}

/* ---- Group list ---- */

.select__group-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

/* ---- Item ---- */

.select__item {
  display: flex;
  align-items: center;
  gap: var(--spacing-2, 8px);
  width: 100%;
  padding: var(--spacing-2, 8px);
  border: none;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--popover-foreground);
  font-family: inherit;
  font-size: var(--font-size-sm);
  line-height: 1;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color var(--duration-100) var(--easing-in-out);
}

.select__item:hover,
.select__item--highlighted {
  background-color: var(--accent);
  color: var(--accent-foreground);
}

.select__item--selected {
  font-weight: var(--font-weight-medium);
}

.select__item--disabled {
  color: var(--muted-foreground);
  cursor: not-allowed;
  pointer-events: none;
}

.select__item:focus-visible {
  outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color);
  outline-offset: -2px;
  border-radius: var(--radius-sm);
}

/* ---- Separator ---- */

.select__separator {
  height: var(--stroke-hairline);
  margin: var(--spacing-1, 4px) calc(-1 * var(--spacing-1, 4px));
  background-color: var(--border);
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .select__trigger,
  .select__icon,
  .select__item {
    transition-duration: 0ms;
  }

  .select__content {
    animation-duration: 0ms;
  }
}
